import { renderNeonConfig } from "../config_template.js";
import { TYPESCRIPT_EXTENSION, asRelativeModulePath, editNeonConfig } from "../config_edit.js";
import { readEnvFile } from "../env_file.js";
import { FUNCTION_SLUG_HELP, FUNCTION_SLUG_PATTERN, deriveFunctionSlug } from "../utils/function_slug.js";
import { resolveOperationById } from "./registry.js";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
// src/functions/scaffold.ts
const operationsFromFlags = (template, choice) => {
	const operations = template.operations ?? [];
	const explicit = choice.operations ?? [];
	if (choice.allOperations && explicit.length > 0) throw new Error("Pass either --all-operations or --operation, not both.");
	if (operations.length === 0 && (choice.allOperations || explicit.length > 0)) throw new Error(`Template "${template.id}" has no operations. Remove --operation and --all-operations.`);
	if (choice.allOperations) return [...operations];
	if (explicit.length > 0) return [...new Set(explicit)].map((id) => resolveOperationById(operations, id));
};
const routeOf = (operation) => operation.route ?? `/${operation.id}`;
const routerSource = (operations) => {
	return `${operations.map((operation, index) => `import op${index} from "./${operation.id}";`).join("\n")}

const routes: Record<
\tstring,
\t{ fetch: (request: Request) => Response | Promise<Response> }
> = {
${operations.map((operation, index) => `\t${JSON.stringify(routeOf(operation))}: op${index},`).join("\n")}
};

export default {
\tfetch(request: Request): Response | Promise<Response> {
\t\tconst { pathname } = new URL(request.url);
\t\tconst route = routes[pathname];
\t\tif (!route) {
\t\t\treturn Response.json(
\t\t\t\t{ error: "Not found", routes: Object.keys(routes) },
\t\t\t\t{ status: 404 },
\t\t\t);
\t\t}
\t\treturn route.fetch(request);
\t},
};
`;
};
const sourceOf = (loaded, path) => {
	const text = loaded.sources.get(path);
	if (text === void 0) throw new Error(`Template "${loaded.template.id}" did not load ${path}.`);
	return text;
};
const planScaffold = (loaded, operations, slug) => {
	const { template } = loaded;
	const env = template.environment.map(({ name }) => name);
	if (!FUNCTION_SLUG_PATTERN.test(slug)) throw new Error(`Invalid function slug "${slug}". ${FUNCTION_SLUG_HELP}`);
	if ((template.operations?.length ?? 0) === 0) return {
		layout: template.layout,
		files: [{
			path: "index.ts",
			contents: sourceOf(loaded, "functions/index.ts")
		}],
		functions: [{
			slug,
			name: template.title,
			file: "index.ts",
			env
		}]
	};
	if (operations.length === 0) throw new Error("Select at least one operation.");
	const modules = operations.map((operation) => ({
		path: `${operation.id}.ts`,
		contents: sourceOf(loaded, operation.source)
	}));
	if (template.layout === "separate") return {
		layout: "separate",
		files: modules,
		functions: operations.map((operation) => ({
			slug: operation.slug ?? deriveFunctionSlug(operation.id),
			name: operation.title,
			operation: operation.id,
			file: `${operation.id}.ts`,
			env
		}))
	};
	return {
		layout: "router",
		files: [...modules, {
			path: "index.ts",
			contents: routerSource(operations)
		}],
		functions: [{
			slug,
			name: template.title,
			file: "index.ts",
			env
		}],
		routes: operations.map(routeOf)
	};
};
const collidingFiles = (targetDir, files) => files.filter(({ path, contents }) => {
	const target = join(targetDir, path);
	return existsSync(target) && readFileSync(target, "utf8") !== contents;
}).map(({ path }) => path);
const writeScaffold = (targetDir, files) => {
	mkdirSync(targetDir, { recursive: true });
	for (const { path, contents } of files) writeFileSync(join(targetDir, path), contents);
};
const planConfigRegistration = (configPath, targetDir, functions) => {
	const created = !existsSync(configPath);
	let source = created ? renderNeonConfig([]) : readFileSync(configPath, "utf8");
	const changes = [];
	const alreadyDeclared = [];
	for (const fn of functions) {
		const result = editNeonConfig(source, {
			kind: "function",
			slug: fn.slug,
			name: fn.name,
			source: asRelativeModulePath(relative(dirname(configPath), resolve(targetDir, fn.file)).split("\\").join("/")),
			env: fn.env,
			typescript: TYPESCRIPT_EXTENSION.test(configPath)
		});
		if (result.changes.length === 0) {
			alreadyDeclared.push(fn.slug);
			continue;
		}
		source = result.source;
		changes.push(...result.changes);
	}
	return {
		...created || changes.length > 0 ? { source } : {},
		created,
		changes,
		alreadyDeclared
	};
};
const planEnvExample = (projectRoot, environment) => {
	const path = join(projectRoot, ".env.example");
	const existing = existsSync(path) ? readFileSync(path, "utf8") : "";
	const declared = new Set(Object.keys(existing ? readEnvFile(path) : {}));
	const missing = environment.filter(({ name }) => !declared.has(name));
	if (missing.length === 0) return {
		path,
		added: []
	};
	const block = missing.map(({ name, description }) => `# ${description}\n${name}=\n`).join("\n");
	return {
		path,
		contents: `${existing}${existing === "" ? "" : existing.endsWith("\n") ? "\n" : "\n\n"}${block}`,
		added: missing.map(({ name }) => name)
	};
};
export { collidingFiles, operationsFromFlags, planConfigRegistration, planEnvExample, planScaffold, writeScaffold };
